  public static BigInteger choose(int n, int r) {
    if (n < 0 || r < 0 || r > n) throw new IllegalArgumentException();
    r = Math.min(r, n - r);
    BigInteger v = BigInteger.ONE;
    for (int i = 1; i <= r; i++)
