import java.util.*;

public class Solution {
  public static int[] solve(int[] a) {
    for (int x : a) if (x < 0 || x > 2) throw new IllegalArgumentException();
    int low = 0, mid = 0, high = a.length - 1;
    while (mid <= high) {
      if (a[mid] == 0) {
        int t = a[low];
        a[low++] = a[mid];
        a[mid++] = t;
      } else if (a[mid] == 1) mid++;
      else {
        int t = a[high];
        a[high--] = a[mid];
        a[mid] = t;
      }
    }
    return a;
  }

  public static void main(String[] args) {
    System.out.println(Arrays.toString(solve(new int[] {2, 0, 2, 1, 1, 0})));
  }
}

Kadane's Algorithm.source:
import java.util.*;

public class Solution {
  public static long solve(int[] a) {
    if (a.length == 0) throw new IllegalArgumentException();
    long end = a[0], best = a[0];
    for (int i = 1; i < a.length; i++) {
      end = Math.max(a[i], end + a[i]);
      best = Math.max(best, end);
    }
    return best;
  }

  public static long brute(int[] a) {
    if (a.length == 0) throw new IllegalArgumentException();
    long best = Long.MIN_VALUE;
    for (int l = 0; l < a.length; l++) {
      long sum = 0;
      for (int r = l; r < a.length; r++) {
        sum += a[r];
        best = Math.max(best, sum);
      }
    }
    return best;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[] {-2, 1, -3, 4, -1, 2, 1, -5, 4}));
  }
}

