    int i = a.length - 2;
    while (i >= 0 && a[i] >= a[i + 1]) i--;
    if (i >= 0) {
      int j = a.length - 1;
      while (a[j] <= a[i]) j--;
      int t = a[i];
      a[i] = a[j];
      a[j] = t;
