    boolean[] seen = new boolean[a.length + 1];
    int repeat = -1;
    for (int x : a) {
      if (x < 1 || x > a.length) throw new IllegalArgumentException();
      if (seen[x]) repeat = x;
      seen[x] = true;
    }
    int missing = -1;
    for (int x = 1; x <= a.length; x++) if (!seen[x]) missing = x;
